	\foralls x \in \RR^d, \quad  f(x) &= \frac{1}{(2\pi)^d} \int_{\RR^d}\hat f(\om)e^{\imath\dotp{x}{\om}}\,\d\om,
\end{align*}
under the same integrability assumptions as in one dimension.


