\eql{\label{eq-model-piece-smooth-2d}
	\Th = \enscond{f \in \Ldeux([0,1]^2)}{ \exists \, \Ga=\bigcup_{i=0}^{K-1}\ga_i, \;
	\norm{f}_{\Cal(\Ga^c)} \leq C_1 \qandq
	|\ga_i| \leq C_2
	 }	 
}
